const legacyBannerSvgBody = legacyBannerSvgMarkup
  .replace(/^<svg[^>]*>/, '')
  .replace(/<\/svg>\s*$/, '')

function LegacyBannerGraphic() {
  return (
    <svg
      width="209"
      height="89"
      viewBox="0 0 209 89"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      focusable="false"
      dangerouslySetInnerHTML={{ __html: legacyBannerSvgBody }}
    />
  )
}

const docsVariantTags = ['default', 'quadrado', 'variant4', 'custom']

const docsHeroStats = [
  {
    title: 'Quando usar',
    text: 'Quando a interface precisa destacar uma campanha, serviço ou acesso externo com uma superfície gráfica fixa, clicável ou apenas visual.',
  },
  {
    title: 'Melhor exploração',
    text: "Use o story 'Interativo' para alternar dimensões, a fonte da arte, o texto alternativo e o destino do link. A documentação compara os tamanhos e mostra o uso de SVG inline e imagem remota.",
  },
  {
    title: 'Comportamento',
    text: 'O componente renderiza um link externo em nova aba quando linkUrl é informada, cai para uma superfície apenas visual quando ela não existe, aceita imagem remota por imageUrl ou mídia inline por image e o story usa o brasão legado como SVG inline no tamanho original.',
  },
] satisfies Array<{ title: string; text: string }>

const defaultExampleCode = `const legacyBannerGraphic = <LegacyBannerGraphic />

<Banner
  image={legacyBannerGraphic}
  imageAlt="${legacyBannerAlt}"
  linkUrl="https://www.procergs.rs.gov.br"
/>`

const typesExampleCode = `const legacyBannerGraphic = <LegacyBannerGraphic />

<Banner type="quadrado" image={legacyBannerGraphic} imageAlt="${legacyBannerAlt}" linkUrl="https://www.procergs.rs.gov.br" />
<Banner type="variant4" image={legacyBannerGraphic} imageAlt="${legacyBannerAlt}" linkUrl="https://www.procergs.rs.gov.br" />`

const customImageExampleCode = `<Banner
  imageUrl="https://www.estado.rs.gov.br/upload/arquivos/202409/banner-plano-na-tua-mao.png"
  imageAlt="Banner Plano na Tua Mão"
  linkUrl="https://www.estado.rs.gov.br/na-tua-mao"
/>`

type BannerInteractiveArgs = {
  bannerType: 'default' | Banner.Type
  imageSource: 'legacySvg' | 'remoteUrl'
  imageUrl: string
  imageAlt: string
  linkUrl: string
}

const meta = {
  title: 'Conteúdo/Banner',
  component: BannerInteractivePreview,
  args: {
    bannerType: 'default',
    imageSource: 'legacySvg',
    imageUrl: customImageUrl,
    imageAlt: legacyBannerAlt,
    linkUrl: defaultLinkUrl,
  },
  parameters: {
    layout: 'padded',
    controls: {
      expanded: true,
      sort: 'requiredFirst',
    },
  },
} satisfies Meta<typeof BannerInteractivePreview>

export default meta

type Story = StoryObj<typeof meta>

function resolveBannerType(bannerType: BannerInteractiveArgs['bannerType']) {
  return bannerType === 'default' ? undefined : bannerType
}

function resolveImageUrl(imageUrl: string) {
  return imageUrl.trim() || undefined
}

function resolveBannerMedia(args: BannerInteractiveArgs): Pick<Banner.Props, 'image' | 'imageUrl'> {
  if (args.imageSource === 'legacySvg') {
    return { image: <LegacyBannerGraphic /> }
  }

  return { imageUrl: resolveImageUrl(args.imageUrl) }
}

function buildBannerCodeSnippet(args: BannerInteractiveArgs) {
  const lines = ['<Banner']

  if (args.bannerType !== 'default') {
    lines.push(`  type="${args.bannerType}"`)
  }

  if (args.imageSource === 'legacySvg') {
    lines.push('  image={<LegacyBannerGraphic />}')
  }

  if (args.imageSource === 'remoteUrl' && args.imageUrl.trim()) {
    lines.push(`  imageUrl="${args.imageUrl}"`)
  }

  if (args.imageAlt.trim() && (args.imageSource === 'legacySvg' || args.imageUrl.trim())) {
    lines.push(`  imageAlt="${args.imageAlt}"`)
  }

  if (args.linkUrl.trim()) {
    lines.push(`  linkUrl="${args.linkUrl}"`)
  }

  lines.push('/>')

  return lines.join('\n')
}

function BannerDefaultPreview() {
  return (
    <div style={{ ...storyDocsStyles.previewStage, justifyItems: 'start' }}>
      <Banner image={<LegacyBannerGraphic />} imageAlt={legacyBannerAlt} linkUrl={defaultLinkUrl} />
    </div>
  )
}

function BannerTypesPreview() {
  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div style={{ display: 'grid', gap: 8 }}>
        <p style={storyDocsStyles.previewLabel}>Default</p>
        <div style={{ ...storyDocsStyles.previewStage, justifyItems: 'start' }}>
          <Banner image={<LegacyBannerGraphic />} imageAlt={legacyBannerAlt} linkUrl={defaultLinkUrl} />
        </div>
      </div>

      <div style={{ display: 'grid', gap: 8 }}>
        <p style={storyDocsStyles.previewLabel}>Quadrado</p>
        <div style={{ ...storyDocsStyles.previewStage, justifyItems: 'start' }}>
          <Banner type="quadrado" image={<LegacyBannerGraphic />} imageAlt={legacyBannerAlt} linkUrl={defaultLinkUrl} />
        </div>
      </div>

      <div style={{ display: 'grid', gap: 8 }}>
        <p style={storyDocsStyles.previewLabel}>Variant4</p>
        <div style={{ ...storyDocsStyles.previewStage, justifyItems: 'start' }}>
          <Banner type="variant4" image={<LegacyBannerGraphic />} imageAlt={legacyBannerAlt} linkUrl={defaultLinkUrl} />
        </div>
      </div>
    </div>
  )
}

function BannerCustomImagePreview() {
  return (
    <div style={{ ...storyDocsStyles.previewStage, justifyItems: 'start' }}>
      <Banner
        imageUrl={customImageUrl}
        imageAlt="Banner Plano na Tua Mão"
        linkUrl="https://www.estado.rs.gov.br/na-tua-mao"
      />
    </div>
  )
}

function BannerInteractivePreview(args: BannerInteractiveArgs) {
  const mediaProps = resolveBannerMedia(args)
  const hasRemoteImage = args.imageSource === 'remoteUrl' && Boolean(resolveImageUrl(args.imageUrl))

  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div style={{ ...storyDocsStyles.previewStage, justifyItems: 'start' }}>
        <Banner
          type={resolveBannerType(args.bannerType)}
          {...mediaProps}
          imageAlt={args.imageAlt}
          linkUrl={args.linkUrl}
        />
      </div>

      <p style={storyDocsStyles.statText}>
        <strong>Tipo ativo:</strong> {args.bannerType}{' '}
        <strong>Fonte da arte:</strong>{' '}
        {args.imageSource === 'legacySvg'
          ? 'SVG inline'
          : hasRemoteImage
            ? 'imagem remota'
            : 'sem arte configurada'}
      </p>

      <pre style={storyDocsStyles.codeBlock}>
        <code>{buildBannerCodeSnippet(args)}</code>
      </pre>
    </div>
  )
}

export const BannerDocumentacao: Story = {
  name: 'Documentação',
  parameters: {
    controls: { disable: true },
  },
  render: () => (
    <DocsStoryLayout>
      <DocsHero
        eyebrow="Documentação guiada"
        title={<h3 style={storyDocsStyles.heroTitle}>Banner</h3>}
        description={
          <>
            O componente <code>Banner</code> renderiza uma superfície gráfica fixa e
            clicável para destacar campanhas, serviços e acessos externos com um
            contrato simples de imagem, link e dimensão.
          </>
        }
        variantTags={docsVariantTags}
        stats={docsHeroStats}
      />

      <SectionCard
        title="Como usar"
        description="Use Banner quando a interface precisar destacar uma chamada gráfica única com ou sem navegação associada. Quando linkUrl estiver presente, o componente funciona como acesso externo; sem ela, renderiza apenas a imagem."
      >
        <ul style={storyDocsStyles.list}>
          <li><code>linkUrl</code> é opcional e define o destino principal do clique quando a peça precisar ser navegável.</li>
          <li><code>image</code> aceita mídia inline em ReactNode, como um <code>svg</code> embutido; <code>imageUrl</code> cobre o caso de arte remota.</li>
          <li>Sem <code>image</code> e sem <code>imageUrl</code>, o Banner não injeta arte automaticamente.</li>
          <li><code>type</code> altera apenas a dimensão visual do bloco, sem mudar o conteúdo renderizado.</li>
        </ul>

        <SandboxExample
          title="Banner básico"
          description="Exemplo mínimo com o brasão legado embutido como SVG inline e um destino externo explícito."
          code={defaultExampleCode}
        >
          <BannerDefaultPreview />
        </SandboxExample>
      </SectionCard>

      <SectionCard
        title="Tipos e dimensões"
        description="A prop type troca apenas o formato da superfície, preservando o mesmo contrato de imagem e link. O comportamento visual cobre o padrão horizontal, o quadrado e a variação horizontal mais alta."
      >
        <ul style={storyDocsStyles.list}>
          <li><code>default</code> usa o formato horizontal base do componente.</li>
          <li><code>quadrado</code> adapta o banner para uma área quadrada de destaque.</li>
          <li><code>variant4</code> amplia a altura do formato horizontal para campanhas com mais respiro visual.</li>
        </ul>

        <SandboxExample
          title="Comparação entre formatos"
          description="Os três formatos principais lado a lado para destacar o impacto visual da prop type."
          code={typesExampleCode}
        >
          <BannerTypesPreview />
        </SandboxExample>
      </SectionCard>

      <SectionCard
        title="Imagem personalizada"
        description="Quando a interface já possui uma arte pronta hospedada externamente, o componente aceita uma URL de imagem e um texto alternativo próprio. Se linkUrl existir, a imagem continua navegável; sem ela, permanece apenas visual."
      >
        <ul style={storyDocsStyles.list}>
          <li><code>imageUrl</code> renderiza uma imagem remota fornecida pelo consumidor.</li>
          <li><code>imageAlt</code> descreve o conteúdo visual do banner e melhora o contexto acessível da imagem ou do link.</li>
          <li><code>linkUrl</code> mantém o destino do clique em nova aba quando for informado.</li>
        </ul>

        <SandboxExample
          title="Banner com imagem remota"
          description="Exemplo com arte externa e descrição própria, mantendo o mesmo comportamento de navegação."
          code={customImageExampleCode}
        >
          <BannerCustomImagePreview />
        </SandboxExample>
      </SectionCard>

      <SectionCard
        title="Props principais"
        description="A API do Banner é propositalmente pequena. As props abaixo cobrem toda a variação suportada pelo componente."
      >
        <ul style={storyDocsStyles.list}>
          <li><code>type</code> é opcional e aceita <code>quadrado</code> ou <code>variant4</code>; quando ausente, o componente usa o formato base.</li>
          <li><code>image</code> aceita mídia inline como ReactNode e é o caminho indicado para SVG embutido.</li>
          <li><code>imageUrl</code> informa uma imagem remota; quando <code>image</code> também existir, a mídia inline tem precedência.</li>
          <li><code>imageAlt</code> descreve a imagem exibida e também ajuda a compor o nome acessível quando o banner for interativo.</li>
          <li><code>linkUrl</code> é opcional; quando ausente, o componente não renderiza link e mostra apenas a imagem.</li>
          <li><code>className</code> permite composição externa sem alterar o contrato principal de uso.</li>
        </ul>
      </SectionCard>

      <SectionCard
        title="Comportamento e limites"
        description="O componente é propositalmente enxuto e não tenta resolver lógica editorial, carregamento de dados ou estados avançados. O consumidor controla apenas a arte, o formato e, quando necessário, o destino do clique."
      >
        <ul style={storyDocsStyles.list}>
          <li>Sem <code>image</code> e sem <code>imageUrl</code>, o Banner não injeta arte automaticamente e a superfície fica vazia.</li>
          <li><code>type</code> altera apenas as dimensões visuais e não introduz novas áreas de conteúdo.</li>
          <li>Com <code>linkUrl</code>, o Banner renderiza uma âncora externa com <code>target=&quot;_blank&quot;</code>; sem ela, renderiza apenas a imagem.</li>
          <li>Quando a arte vem por <code>image</code>, especialmente com SVG inline, use <code>imageAlt</code> para manter um nome acessível coerente.</li>
          <li>Se a interface exigir textos, botões, overlays ou múltiplas ações, esse conteúdo deve ser modelado em outro componente de maior composição.</li>
        </ul>
      </SectionCard>
    </DocsStoryLayout>
  ),
}

